"""Read-only cleaning inspector for the production workbench."""

CLEANING_HTML = '''<dialog id="board-cleaning" aria-labelledby="board-cleaning-title"><div class="cleaning-heading"><h2 id="board-cleaning-title">清洗详情</h2><button id="board-cleaning-refresh" type="button">刷新结果</button><button id="board-cleaning-close" type="button">关闭清洗详情</button></div><p id="board-cleaning-status" role="status" aria-live="polite"></p><div id="board-cleaning-body"></div></dialog>'''

CLEANING_CSS = '''
.cleaning-chain{margin:18px 0 18px 10px;padding-left:22px;border-left:2px solid #b9cdbd}.cleaning-chain>.cleaning-step{position:relative;border:1px solid #dedfdb;border-radius:10px;padding:16px;margin:0 0 22px;background:#fff}.cleaning-chain>.cleaning-step:before{content:'';position:absolute;width:12px;height:12px;border-radius:50%;background:#39764b;border:3px solid #fff;left:-32px;top:17px}.cleaning-chain>.cleaning-step:not(:last-child):after{content:'↓';position:absolute;left:-30px;bottom:-22px;color:#39764b}.cleaning-node-info{margin:14px 0;color:#69736b;font-size:13px}.cleaning-thumbnail{display:block;width:100%;min-height:200px;padding:0;border:0;border-radius:6px;background:#f6f6f4;cursor:zoom-in;margin-bottom:10px}.cleaning-image p{font-size:13px}
#board-cleaning{width:min(1100px,94vw);max-height:88vh;overflow:auto;border:1px solid #dedfdb;border-radius:14px;padding:22px;color:#202421}#board-cleaning::backdrop{background:#17221c66}.cleaning-heading{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.cleaning-heading h2{margin-right:auto}#board-cleaning p{overflow-wrap:anywhere;font-size:13px;line-height:1.6}.cleaning-snapshot{padding:12px;background:#f3f6f2;border-radius:10px;margin:12px 0}.cleaning-step{border-top:1px solid #dedfdb;padding:14px 0}.cleaning-step summary{cursor:pointer;font-weight:700}.cleaning-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px;margin:12px 0}.cleaning-image{border:1px solid #dedfdb;border-radius:10px;padding:12px;min-width:0}.cleaning-image img{display:block;width:100%;height:200px;object-fit:contain;background:#f6f6f4}.cleaning-image small{overflow-wrap:anywhere;display:block;color:#69736b}.cleaning-filters{display:flex;gap:10px;flex-wrap:wrap;margin:12px 0}.cleaning-filters select,.cleaning-filters input{padding:8px;border:1px solid #dedfdb;border-radius:8px;max-width:100%}
'''

CLEANING_JS = r'''
const cleaningPanel={taskId:null,token:0,timer:null,abort:null,urls:new Set(),filters:new Map()};
function mountBoardCleaning(item,body){const button=document.createElement('button');button.type='button';button.textContent='查看清洗逐图结果';button.onclick=()=>openBoardCleaning(item.task_id);body.append(button)}
function cleaningText(parent,tag,text){const el=document.createElement(tag);el.textContent=text;parent.append(el);return el}
function boardCleaningReason(reason){const labels={MATCH:'符合条件',MISMATCH:'不符合条件',FACT_UNAVAILABLE:'证据不足',DETECTOR_ERROR:'检测器异常',DETECTOR_OUTPUT_INVALID:'检测结果格式无效'};return `${reason.rule_id}：${labels[reason.reason_code]||reason.reason_code}（${reason.verdict}）`+(reason.reason_summary?`：${reason.reason_summary}${reason.reason_truncated?'（摘要已截断）':''}`:reason.verdict==='pass'?'':'；未保存具体原因摘要')}
function boardCleaningItems(step,filter){return step.items.filter(item=>(filter.status==='all'||item.status===filter.status)&&(!filter.tag||filter.tag==='all'||item.reasons.some(reason=>filter.tag==='rule:'+reason.rule_id||filter.tag==='reason:'+reason.reason_code))&&(!filter.query||item.reasons.some(reason=>boardCleaningReason(reason).includes(filter.query))))}
function clearBoardCleaning(){clearTimeout(cleaningPanel.timer);cleaningPanel.timer=null;cleaningPanel.abort?.abort();cleaningPanel.abort=null;for(const url of cleaningPanel.urls)URL.revokeObjectURL(url);cleaningPanel.urls.clear()}
function closeBoardCleaning(){if(typeof assetViewer!=='undefined'&&$('asset-viewer').open)$('asset-viewer').close();cleaningPanel.token++;cleaningPanel.taskId=null;clearBoardCleaning();$('board-cleaning-body').replaceChildren()}
function boardCleaningSnapshot(parent,execution){const box=document.createElement('div');box.className='cleaning-snapshot';parent.append(box);if(!execution?.model){cleaningText(box,'p','未保存 VLM 执行快照，不使用当前配置补写历史模型和指令。');if(execution?.backend_refs)cleaningText(box,'p','算子：'+execution.backend_refs.join('、'));return}cleaningText(box,'p',`清洗模型：${execution.model.provider} / ${execution.model.name}（${execution.model.id}）`);cleaningText(box,'p','执行指令：'+execution.instruction);cleaningText(box,'p',`算子：${execution.backend_ref} · 提示版本：${execution.prompt_version}`);cleaningText(box,'small','配置摘要：'+execution.config_digest)}
async function boardCleaningImage(taskId,candidateId,row,button,token){button.disabled=true;button.textContent='加载缩略图…';try{const response=await fetch(`/v1/retrieval/tasks/${encodeURIComponent(taskId)}/cleaning/candidates/${encodeURIComponent(candidateId)}/preview`,{headers,cache:'no-store',signal:cleaningPanel.abort.signal});if(!response.ok)throw new Error('图片不可读取或已撤权');const blob=await response.blob();if(!['image/jpeg','image/png'].includes(blob.type)||blob.size>10*1024*1024)throw new Error('图片格式或大小无效');if(token!==cleaningPanel.token||!row.isConnected)return;const url=URL.createObjectURL(blob);cleaningPanel.urls.add(url);row._previewUrl=url;const img=document.createElement('img');img.alt='清洗图片，点击查看证据';img.src=url;img.onerror=()=>{releaseCleaningRow(row);button.replaceChildren();button.textContent='图片解码失败，点击重试';button.onclick=()=>boardCleaningImage(taskId,candidateId,row,button,token)};button.textContent='';button.replaceChildren(img);button.disabled=false;button.onclick=()=>openAssetViewer(row)}catch(error){if(error.name!=='AbortError'&&token===cleaningPanel.token&&row.isConnected){button.disabled=false;button.textContent=error.message+'，点击重试';button.onclick=()=>boardCleaningImage(taskId,candidateId,row,button,token)}}}
function releaseCleaningRow(row){if(row._previewUrl){URL.revokeObjectURL(row._previewUrl);cleaningPanel.urls.delete(row._previewUrl);row._previewUrl=null}}
function boardCleaningTags(step){const tags=new Map();for(const item of step.items)for(const reason of item.reasons){tags.set('rule:'+reason.rule_id,'规则：'+reason.rule_id);tags.set('reason:'+reason.reason_code,'原因：'+({MATCH:'符合条件',MISMATCH:'不符合条件',FACT_UNAVAILABLE:'证据不足',DETECTOR_ERROR:'检测器异常',DETECTOR_OUTPUT_INVALID:'检测结果格式无效'}[reason.reason_code]||reason.reason_code))}return tags}
function boardCleaningStep(parent,run,step,taskId,preview,token,index=0){
 const key=run.operation_id+':'+run.output_version+':'+step.step_id,filter=cleaningPanel.filters.get(key)||{status:'all',query:'',tag:'all',expanded:index===0};cleaningPanel.filters.set(key,filter);
 const detail=document.createElement('details');detail.className='cleaning-step';detail.open=filter.expanded;parent.append(detail);cleaningText(detail,'summary',`节点 ${index+1} · ${step.step_id} · 输入 ${step.counts.input} · 本步保留 ${step.counts.retained} · 淘汰 ${step.counts.rejected} · 待复核 ${step.counts.review}`);
 const metadata=document.createElement('details');metadata.className='cleaning-node-info';detail.append(metadata);cleaningText(metadata,'summary','查看节点规则与执行信息');cleaningText(metadata,'p',`算子：${step.backend_ref} · 输出版本：${run.output_version}`);
 const node=run.execution?.nodes?.find(item=>item.backend_ref===step.backend_ref);if(node){cleaningText(metadata,'p','对应诉求：'+node.source);cleaningText(metadata,'p','本节点指令：'+node.instruction)}for(const rule of step.rules)cleaningText(metadata,'p',`${rule.rule_id}：${rule.predicate} ${rule.operator} ${JSON.stringify(rule.value)}`);
 const controls=document.createElement('div');controls.className='cleaning-filters';detail.append(controls);
 const select=document.createElement('select');select.setAttribute('aria-label',step.step_id+' 筛选清洗结果');for(const [value,label] of [['all','全部图片'],['retained','本步保留'],['rejected','淘汰'],['review','待复核']]){const option=cleaningText(select,'option',label);option.value=value}select.value=filter.status;
 const tags=document.createElement('select');tags.setAttribute('aria-label',step.step_id+' 筛选规则或原因标签');const all=cleaningText(tags,'option','全部标签');all.value='all';for(const [value,label] of boardCleaningTags(step)){const option=cleaningText(tags,'option',label);option.value=value}tags.value=filter.tag||'all';
 const query=document.createElement('input');query.type='search';query.placeholder='搜索原因或规则';query.setAttribute('aria-label',step.step_id+' 搜索清洗原因');query.value=filter.query;controls.append(select,tags,query);
 const count=document.createElement('p'),grid=document.createElement('div'),more=document.createElement('button');grid.className='cleaning-grid';more.type='button';more.textContent='加载更多图片';detail.append(count,grid,more);let limit=filter.limit||12;const rendered=new Map();
 const render=()=>{const items=boardCleaningItems(step,filter),wanted=new Set(items.slice(0,limit).map(item=>item.candidate_id));for(const [id,row] of rendered){if(!wanted.has(id)){releaseCleaningRow(row);row.remove();rendered.delete(id)}}count.textContent=`匹配 ${items.length} 张 · 已显示 ${Math.min(limit,items.length)} 张`;
 for(const item of items.slice(0,limit)){if(rendered.has(item.candidate_id))continue;const row=document.createElement('article');row.className='cleaning-image';grid.append(row);rendered.set(item.candidate_id,row);
 row._asset={title:'清洗图片 · '+item.candidate_id,url:preview?`/v1/retrieval/tasks/${encodeURIComponent(taskId)}/cleaning/candidates/${encodeURIComponent(item.candidate_id)}/preview`:null,lines:()=>['本步结论：'+({retained:'本步保留，不等于正式入选',rejected:'淘汰',review:'待复核'})[item.status],'素材版本：'+item.asset_version,'步骤：'+step.step_id,'输出版本：'+run.output_version,...item.reasons.map(boardCleaningReason),...(node?['对应诉求：'+node.source,'执行指令：'+node.instruction]:[])]};
 const button=cleaningText(row,'button',preview?'加载缩略图…':'暂无可用缩略图');button.className='cleaning-thumbnail';button.type='button';button.setAttribute('aria-label','查看清洗图片与证据');button.onclick=()=>openAssetViewer(row);cleaningText(row,'strong',({retained:'本步保留',rejected:'淘汰',review:'待复核'})[item.status]||item.status);for(const reason of item.reasons)cleaningText(row,'p',boardCleaningReason(reason));if(preview)boardCleaningImage(taskId,item.candidate_id,row,button,token)}more.hidden=items.length<=limit};
 const reset=()=>{if(typeof assetViewer!=='undefined'&&$('asset-viewer').open)$('asset-viewer').close();filter.limit=limit=12;render()};select.onchange=()=>{filter.status=select.value;reset()};tags.onchange=()=>{filter.tag=tags.value;reset()};query.oninput=()=>{filter.query=query.value.trim();reset()};more.onclick=()=>{limit+=12;filter.limit=limit;render()};detail.addEventListener('toggle',()=>{filter.expanded=detail.open;if(detail.open)render()});if(detail.open)render();
}
async function readBoardCleaning(){const taskId=cleaningPanel.taskId;if(!taskId)return;clearBoardCleaning();const token=++cleaningPanel.token;cleaningPanel.abort=new AbortController();const current=()=>token===cleaningPanel.token&&taskId===cleaningPanel.taskId&&$('board-cleaning').open;const body=$('board-cleaning-body');body.replaceChildren();$('board-cleaning-status').textContent='正在读取当前版本清洗记录…';try{const base=`/v1/retrieval/tasks/${encodeURIComponent(taskId)}`;const [task,data]=await Promise.all([api(base),api(base+'/cleaning/steps')]);if(!current())return;const operationId=task.active_cleaning_operation_id||data.runs?.[0]?.operation_id;const status=operationId?await api(base+'/cleaning/status?operation_id='+encodeURIComponent(operationId)):null;if(!current())return;const latest=await api(base);if(!current())return;if(data.revision!==task.confirmed_revision||data.generation!==task.run_generation||task.task_version!==latest.task_version||task.run_generation!==latest.run_generation||task.confirmed_revision!==latest.confirmed_revision)throw new Error('任务版本已变化，请刷新结果');$('board-cleaning-title').textContent='清洗详情 · '+taskId;const progress=status?.progress;$('board-cleaning-status').textContent=progress?`已完整判定 ${progress.completed}/${progress.total} 张 · 通过 ${progress.passed} · 淘汰 ${progress.rejected} · 待复核 ${progress.review} · 未完成 ${progress.pending}`:'当前没有可用的逐图执行进度';if(status?.status==='retry_wait')cleaningText(body,'p',`等待重试 ${status.attempts}/${status.max_attempts}；下次不早于 ${new Date(status.next_attempt_at*1000).toLocaleTimeString()}`);if(status?.status==='failed')cleaningText(body,'p',`清洗已停止：${status.code}；${status.message}`);if(status?.status==='superseded')throw new Error('清洗所属版本已失效，请刷新线路');cleaningText(body,'p','这里只读查看。本步保留不等于最终入选；待复核不能直接改为通过。');if(data.available){for(const run of data.runs){cleaningText(body,'p',`运行 ${run.operation_id} · revision ${run.revision} · generation ${run.generation}`);boardCleaningSnapshot(body,run.execution);cleaningText(body,'p',run.note);cleaningText(body,'p','节点连线表示配方顺序；各步检测同一候选集，不表示上一步保留数流入下一步。');const chain=document.createElement('div');chain.className='cleaning-chain';body.append(chain);run.steps.forEach((step,index)=>boardCleaningStep(chain,run,step,taskId,data.candidate_preview_available,token,index))}}else{boardCleaningSnapshot(body,status?.execution);cleaningText(body,'p',operationId?'尚未发布完整步骤结果，已保存判定见下方；未完成的图片不计为待复核。':'尚未启动已批准的清洗操作。');for(const item of progress?.candidate_results||[])cleaningText(body,'p',item.candidate_id+'：'+({pass:'通过',fail:'淘汰',unknown:'待复核'})[item.verdict]);if(progress?.partial_candidate){cleaningText(body,'h3','当前图片 '+progress.partial_candidate);for(const node of progress.completed_nodes||[])cleaningText(body,'p',`${node.step_id}：${({pass:'通过',fail:'淘汰',unknown:'待复核'})[node.verdict]||node.verdict} · ${node.reasons.map(reason=>reason.reason_summary||reason.reason_code).join('；')}`);cleaningText(body,'p','下一节点：'+(progress.next_node||'等待本图完整保存'))}}if(['queued','running','retry_wait'].includes(status?.status))cleaningPanel.timer=setTimeout(()=>{if(current())readBoardCleaning()},3000)}catch(error){if(current()){$('board-cleaning-status').textContent='清洗详情读取失败：'+error.message;body.replaceChildren()}}}
function openBoardCleaning(taskId){closeBoardCleaning();cleaningPanel.filters.clear();cleaningPanel.taskId=taskId;const dialog=$('board-cleaning');if(!dialog.open)dialog.showModal();readBoardCleaning()}
$('board-cleaning-close').onclick=()=>$('board-cleaning').close();$('board-cleaning').addEventListener('close',closeBoardCleaning);$('board-cleaning-refresh').onclick=readBoardCleaning;
'''
